ntc_rg408:
;## ntc_ltoa ntc_ldata ntc_data
; Long at (HL) to text at DE, 0 at the end. jp (ix) back. Uses IY.
ntc_ltoa:
			ld (ntc_ldst), de
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			ld de, (ntc_ldst)
			ld a, (ntc_la+3)
			or a
			jp p, ntc_lta_pos
			ld a, '-'
			ld (de), a
			inc de
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lta_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_lpow10
ntc_lta_pow:
			ld a, (iy+0)
			or (iy+1)
			or (iy+2)
			or (iy+3)
			jr z, ntc_lta_last
			ld c, '0'
ntc_lta_sub:
			ld hl, ntc_la
			ld a, (hl)
			sub (iy+0)
			ld (ntc_lt), a
			inc hl
			ld a, (hl)
			sbc a, (iy+1)
			ld (ntc_lt+1), a
			inc hl
			ld a, (hl)
			sbc a, (iy+2)
			ld (ntc_lt+2), a
			inc hl
			ld a, (hl)
			sbc a, (iy+3)
			ld (ntc_lt+3), a
			jr c, ntc_lta_dig
			ld hl, (ntc_lt)
			ld (ntc_la), hl
			ld hl, (ntc_lt+2)
			ld (ntc_la+2), hl
			inc c
			jr ntc_lta_sub
ntc_lta_dig:
			ld a, c
			cp '0'
			jr nz, ntc_lta_out
			ld a, (ntc_lead)
			or a
			jr z, ntc_lta_skip
			ld a, c
ntc_lta_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_lta_skip:
			ld bc, 4
			add iy, bc
			jr ntc_lta_pow
ntc_lta_last:
			ld a, (ntc_la)
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_lpow10:		dd 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 0

ntc_rg408_e:
			IF ($ < 58624) && (ntc_rg409_e - ntc_rg409 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg409_e - ntc_rg409 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg409:
;## ntc_font
; 8x8 font buffer, chars 32-126, 8 bytes each, bit 7 = leftmost pixel.
; The platform fills it at start: the CPC copies its own font from the
; lower ROM (#3900), so text looks like the CPC's.
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:		ds 95 * 8

; ============================================================
; Platform class capabilities
; ============================================================

ntc_rg409_e:
			IF ($ < 58624) && (ntc_rg410_e - ntc_rg410 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg410_e - ntc_rg410 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg410:
;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

ntc_rg410_e:
			IF ($ < 58624) && (ntc_rg411_e - ntc_rg411 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg411_e - ntc_rg411 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg411:
;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode (0, 1: 40 columns, 2: 80)
ntc_sinit:		db 0			; 1 once the tilemap is set up
ntc_scols:		db 40			; columns
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 8			; the 8 half rows this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_zxvs:		db 0			; 1: this interrupt is a frame's first (line 0 passed: to ntc_isl_tick in C)
ntc_zxline:		dw 0			; the raster line the line interrupt is set to
ntc_zxsel:		db 0			; the NextReg selected (#243B) by code interrupts can get into: the
								; handler selects it again after its own (store it, then select)
ntc_zxl2:		db 0			; 1 = Layer 2 is on (Graphics); Mode turns it off
ZXN_MAP			equ #E000		; the tilemap (bank 5 + #2000: NextReg #6E = #20)
ZXN_TILES		equ #EC00		; its characters (bank 5 + #2C00: NextReg #6F = #2C)
ZXN_ROWS		equ 32
ZXN_PAPER		equ #02			; RRRGGGBB: blue
ZXN_INK			equ #FC			; yellow

ntc_rg411_e:
			IF ($ < 58624) && (ntc_rg412_e - ntc_rg412 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg412_e - ntc_rg412 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg412:
;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			cp 32
			jr c, ntc_pc_bad
			cp 127
			jr c, ntc_zx_put
ntc_pc_bad:
			ld a, '?'
			jr ntc_zx_put

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = an 8 byte glyph in ntc_font (ZOSCII text): that
; character at the cursor, the cursor on (a glyph not in ntc_font: ?)
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld hl, -ntc_font
			add hl, de				; HL = the glyph's offset: 0 .. 95 * 8 - 1
			ld a, h
			cp (95 * 8) / 256
			jr c, ntc_pg_in
			jr nz, ntc_pc_bad
			ld a, l
			cp (95 * 8) & 255
			jr nc, ntc_pc_bad
ntc_pg_in:
			srl h
			rr l
			srl h
			rr l
			srl h
			rr l
			ld a, l
			add a, 32
			; fall into ntc_zx_put

; A = a character code: into the tilemap at the cursor (its tile), the cursor on
ntc_zx_put:
			ld c, a
			ld a, (ntc_cury)		; HL = ZXN_MAP + row * columns + column
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; row * 40
			ld a, (ntc_scols)
			cp 80
			jr nz, $+3
			add hl, hl				; row * 80
			ld a, (ntc_curx)
			ld e, a
			ld d, ZXN_MAP / 256		; (ZXN_MAP's low byte is 0)
			add hl, de
			ld (hl), c
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp ZXN_ROWS
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

ntc_rg412_e:
			IF ($ < 58624) && (ntc_rg413_e - ntc_rg413 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg413_e - ntc_rg413 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg413:
;## ntc_plat_scroll ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-31 up one, clear row 31
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, ZXN_ROWS - 1
			ld (ntc_cury), a
			ld a, (ntc_scols)
			ld c, a
			ld b, 0					; BC = a row
			ld hl, ZXN_MAP
			add hl, bc
			ld de, ZXN_MAP
			cp 80
			ld bc, (ZXN_ROWS - 1) * 40
			jr nz, ntc_sc_40
			ld bc, (ZXN_ROWS - 1) * 80
ntc_sc_40:
			ldir					; DE = the last row
			ld h, d
			ld l, e
			ld (hl), ' '
			inc de
			ld c, a
			dec c
			ld b, 0
			ldir
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - the whole tilemap spaces, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, ZXN_MAP
			ld de, ZXN_MAP + 1
			ld bc, ZXN_ROWS * 80 - 1
			ld (hl), ' '
			ldir
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

ntc_rg413_e:
			IF ($ < 58624) && (ntc_rg414_e - ntc_rg414 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg414_e - ntc_rg414 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg414:
;## ntc_plat_frame ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_frame - wait for the end of the display (raster line 192: the
; bottom border starts). Normal mode: interrupts in while waiting
; ------------------------------------------------------------
ntc_plat_frame:
			ld (ntc_klink), ix		; (ntc_klink: the return - IX runs ntc_fr_line)
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_go
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_fr_go:
			ld bc, #243B
ntc_fr_out:						; first out of lines 192 and on (the border, the sync)
			ld ix, ntc_fr_out2
			jr ntc_fr_line
ntc_fr_out2:
			jr nz, ntc_fr_out
ntc_fr_in:						; then wait for line 192
			ld ix, ntc_fr_in2
			jr ntc_fr_line
ntc_fr_in2:
			jr z, ntc_fr_in
			jr ntc_fr_at
; the raster line (NextReg #1E: its bit 8, #1F: bits 0-7), its two halves read
; again until bit 8 is the same both times (line 255 to 256 between them reads
; as 0): NZ = line 192 or more. Back to IX; keeps BC (#243B)
ntc_fr_line:
			ld a, #1E
			ld (ntc_zxsel), a		; (interrupts are in: the handler selects it again)
			out (c), a
			inc b
			in d, (c)
			dec b
			ld a, #1F
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in e, (c)
			dec b
			ld a, #1E
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in a, (c)
			dec b
			cp d
			jr nz, ntc_fr_line
			ld d, a
		IF NTC_ZXIRQ					; (the interrupt handler is in the program: normal mode)
			ld a, (ntc_irqset)		; the line interrupt's chain: a pulse that came while interrupts
			or a					; were off was lost - the wait here is where a program with long
			jr z, ntc_fr_lok		; stretches of them lets interrupts in, so see that the raster has
			ld a, d					; not passed the line set without its interrupt (the same line in
			and 1					; the same stretch every frame: Frame paces a program to the
			ld h, a					; frame, so a lost one would stay lost): then the handler is
			ld l, e					; called, to count the ticks missed and set the line ahead
			push de
			ex de, hl
			ld hl, (ntc_zxline)
			or a
			sbc hl, de				; the line set - now (mod 312): 0-56 = ahead, its pulse comes (the
			jr nc, ntc_fr_l1		; chain sets the next line 52 on at most); more = passed, lost
			ld de, 312
			add hl, de
ntc_fr_l1:
			ld de, -57
			add hl, de
			jr nc, ntc_fr_l2
			di
			call ntc_irq			; (ends with ei: as its interrupt would)
ntc_fr_l2:
			pop de
			ld bc, #243B
ntc_fr_lok:
		ENDIF
			ld a, d
			rra
			jr c, ntc_fr_lnz		; 256 and on
			ld a, e
			cp 192
			ccf
			sbc a, a				; #FF: 192-255, 0: below
			jp (ix)
ntc_fr_lnz:
			or 1
			jp (ix)
ntc_fr_at:
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_done
			ld sp, (ntc_ip)
ntc_fr_done:
			ld ix, (ntc_klink)
			jp (ix)

ntc_rg414_e:
			IF ($ < 58624) && (ntc_rg415_e - ntc_rg415 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg415_e - ntc_rg415 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg415:
;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - the end: interrupts off, a soft reset (NextReg 2 bit 0) -
; back to NextZXOS (a NEX file has no caller to return to)
; ------------------------------------------------------------
ntc_plat_exit:
			di
			ld bc, #243B
			ld a, #02
			out (c), a
			inc b
			ld a, 1
			out (c), a
ntc_ex_wait:
			jr ntc_ex_wait

ntc_rg415_e:
			IF ($ < 58624) && (ntc_rg416_e - ntc_rg416 + $ > 48640)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BE00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg416_e - ntc_rg416 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg416:
;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the program's arrays and the Memory class's heap in
; main memory must not use. ZXN_MEMTOP (the compiler's): #BA00 with the FileSystem or Loader
; class (their DOS area #BA00-#BDFF, then the stack to #C000), #BE00 without (20261118-1). A
; program that runs on over the stack has its arrays in #C000-#FFFF, where the build has
; already checked them against what is there: the top is then #FD00 (the start-up stub).
; (20261118-1: it was #BA00 always, so such a program stopped at its start with GURU 001.)
; Called on the real stack (call / ret).
ntc_plat_memtop:
			IF ntc_free > #C000		; fwdref-ok
			ld hl, #FD00
			ELSE
			ld hl, ZXN_MEMTOP
			ENDIF
			ret


ntc_pgloaded:	db 4		; the pages taken from the start (Loaded n, Option SaveNex, Option Memory Reserve Pages, the program's own: 0 1 2 5): how many, then the pages
			dw 0, 1, 2, 5
ntc_rg416_e:
ntc_end:				; the end of the program (and of its file)
var_bigtext_y		equ var_bigtext_x + 2
var_damage_y		equ var_damage_x + 2
var_damage_t		equ var_damage_x + 4
var_killalien_c		equ var_killalien_n + 2
var_killalien_r		equ var_killalien_n + 4
var_boom_y		equ var_boom_x + 2
var_tiles_rect_y		equ var_tiles_rect_x + 2
var_tiles_rect_w		equ var_tiles_rect_x + 4
var_tiles_rect_h		equ var_tiles_rect_x + 6
var_tiles_rect_t		equ var_tiles_rect_x + 8
var_sfx_play_period		equ var_sfx_play_ch + 2
var_sfx_play_sl		equ var_sfx_play_ch + 4
var_sfx_play_volume		equ var_sfx_play_ch + 6
var_sfx_play_frames		equ var_sfx_play_ch + 8
var_sfx_play_noise		equ var_sfx_play_ch + 10
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack #C000 down (the platform's)"
			DISPLAY "NTC memory: Reserved #C000-#E4FF"
			DISPLAY "NTC memory: Reserved #BE00-#BFFF (platform zxn)"
			DISPLAY "NTC memory: Reserved #FD00-#FFFF (platform zxn)"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
			IF (ntc_bssfrom < 58624) && (ntc_bssfrom + ntc_bss_size > 48640)	; fwdref-ok
ntc_bss		equ 58624		; after Option Memory Reserved #BE00-#E4FF
			ELSEIF (ntc_bssfrom < 65536) && (ntc_bssfrom + ntc_bss_size > 64768)	; fwdref-ok
ntc_bss		equ 65536		; after Option Memory Reserved #FD00-#FFFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
			ASSERT ntc_bss + ntc_bss_size <= #10000, "out of memory: the arrays (after the last Option Memory Reserved / Paged range) do not fit below #10000"	; fwdref-ok
arr_alive		equ ntc_bss + 0		; 55 bytes
arr_bx		equ ntc_bss + 55		; 6 bytes
arr_by		equ ntc_bss + 61		; 6 bytes
arr_bon		equ ntc_bss + 67		; 6 bytes
arr_spr_tab		equ ntc_bss + 73		; 640 bytes
arr_sfx_per		equ ntc_bss + 713		; 6 bytes
arr_sfx_slide		equ ntc_bss + 719		; 6 bytes
arr_sfx_vol		equ ntc_bss + 725		; 6 bytes
arr_sfx_total		equ ntc_bss + 731		; 6 bytes
arr_sfx_left		equ ntc_bss + 737		; 6 bytes
arr_sfx_nse		equ ntc_bss + 743		; 6 bytes
ntc_bss_size	equ 749
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 49152) || (ntc_bss >= 58624), "the program (or its arrays) reaches into Option Memory Reserved #C000-#E4FF (Tiles.cls line 12)"
			ASSERT (ntc_free <= 48640) || (ntc_bss >= 49152), "the program (or its arrays) reaches into the platform's reserved #BE00-#BFFF (platform zxn: Option Memory Available frees it)"
			ASSERT (ntc_free <= 64768) || (ntc_bss >= 65536), "the program (or its arrays) reaches into the platform's reserved #FD00-#FFFF (platform zxn: Option Memory Available frees it)"

; ============================================================
; ZX Spectrum Next: the start stub (bank 5, page 11 at #7E00) and the NEX file
; ============================================================
			IF NTC_PLATRSV == 0		; (with the platform's #BA00-#FFFF Reserved in the map, the build goes round it)
			ASSERT ntc_free <= #BA00, "the program and its arrays must end below #BA00 (the FileSystem class's DOS area is #BA00-#BDFF, the stack #BE00-#BFFF, the screen #C000-#FFFF)"
			ENDIF
			MMU 3, 11			; page 11 (bank 5's second half) at #6000 to assemble the stub
			org #7E00
zxn_boot:
			di
			ld bc, #243B		; NextReg select (#253B: its value)
			ld a, 6			; Peripheral 2: the NMI buttons off (bit 3 Multiface M1, bit 4 DivMMC DRIVE)
			out (c), a
			inc b
			in a, (c)
			and %11100111
			out (c), a
			dec b
; DivMMC: its automatic paging and its entry points stay exactly as NextZXOS left them
; (NextRegs #B8-#BB untouched). Until 20261110-2 the stub cut them to "rst 8 with ROM 3"
; (#B8 = 2, #B9 = 0, #BB = 0): every emulator ran that; four games crashed on a real Next
; at their first esxDOS call, and #BB = 0 also cleared bit 6, the 0x1FF8-0x1FFF exit the DOS
; leaves its memory by - the emulators do not model those registers (ZEsarUX ignores them),
; so nothing here can prove it; the DOS's own setting is the one every working NEX runs
; with. NextZXOS's setting traps rst 8
; (and #0038, #3Dxx, the tape entries) only with ROM 3 paged, which a program never has
; except round an esxDOS call (the FileSystem class, CyborgOS's SD drive: ROM 3 in
; slots 0-1, rst 8, ROM 3 off), so nothing pages DivMMC in by accident
; (no out (#E3): DivMMC's memory is already out when a NEX starts - .nexload leaves it so -
; and writing the port selects its RAM bank 0 and drops MAPRAM, which loses NextZXOS's esxDOS
; state: its file handles are in DivMMC RAM. With it untouched, RST 8 calls work from the program
; (automap on, the ROM in slots 0-1 for the call: CyborgOS's SD drive does that)
			ld a, #8E		; the 128K paging: normal mode, ROM 0 (no change to slots 6-7: bit 3 = 0). NextZXOS's
			out (c), a		; DivMMC entry points (rst 8, #0038, #3Dxx, the tape addresses) trap only with ROM 3
			inc b			; selected: with ROM 0 none can, whatever a slot holds; an esxDOS call selects ROM 3
			xor a			; round its rst 8 and puts ROM 0 back (the FileSystem class, CyborgOS's SD drive)
			out (c), a
			dec b
			ld a, 7			; CPU speed: 28MHz
			out (c), a
			inc b
			ld a, 3
			out (c), a
			dec b
			ld hl, zxn_mmu		; the slots but 3
			ld e, 7
zxn_bmmu:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, zxn_bmmu
			jp zxn_boot2 + #8000	; on in the copy at #E000-#FFFF (page 11 in slot 7)
zxn_boot2:
			ld a, #53			; slot 3: page 3
			out (c), a
			inc b
			ld a, 3
			out (c), a
			ld hl, #C9FB		; #0038: ei, ret until ntc_plat_irqon puts its jump there
			ld (#0038), hl
			im 1
			jp ntc_start
zxn_mmu:	db #50, 0, #51, 1, #52, 2, #54, 4, #55, 5, #56, 10, #57, 11
			SAVENEX OPEN "SIEGE.NEX", zxn_boot, #BFFE
			SAVENEX CORE 3, 0, 0
			SAVENEX CFG 0
			SAVENEX BANK 5, 2, 0, 1
			SAVENEX CLOSE